// Sandtable V2: an independent, local-only interaction prototype.
// These fixtures are deliberately synthetic. Nothing here calls the simulation core.
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const paths = {
  chart:'M3 3v18h18M6 14l4-5 4 3 6-8', table:'M3 4h18v16H3zM3 9h18M9 4v16M15 4v16',
  flask:'M9 3h6M10 3v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3M7 15h10',
  terminal:'M3 4h18v16H3zM7 9l3 3-3 3M13 15h4', exchange:'M4 7h14l-3-3M20 17H6l3 3M20 4v6M4 14v6',
  search:'m20 20-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',
  'panel-left':'M3 4h18v16H3zM9 4v16M6 8v8', 'panel-right':'M3 4h18v16H3zM15 4v16M18 8v8',
  'folder-open':'M3 8V5h6l2 3h10v12H3zM3 11h18', 'file-code':'M14 3H5v18h14V8l-5-5v5h5M10 12l-3 3 3 3M14 12l3 3-3 3',
  'git-branch':'M6 6v12M6 9c10 0 12 0 12-4M8 4a2 2 0 1 1-4 0 2 2 0 0 1 4 0M8 20a2 2 0 1 1-4 0 2 2 0 0 1 4 0M20 3a2 2 0 1 1-4 0 2 2 0 0 1 4 0',
  sliders:'M4 5h16M4 12h16M4 19h16M8 2v6M16 9v6M10 16v6', info:'M12 11v6M12 7v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  check:'m5 12 4 4L19 6', circlecheck:'m8 12 3 3 5-6M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  warning:'m12 3 10 18H2L12 3Zm0 6v5m0 3v1', cross:'m6 6 12 12M6 18 18 6', chevron:'m8 5 7 7-7 7',
  download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5', play:'m8 4 13 8-13 8V4Z',
  copy:'M8 8h13v13H8zM16 8V3H3v13h5', save:'M4 3h13l4 4v14H3V3h1Zm3 0v7h10V3M7 21v-7h10v7',
  undo:'m8 4-5 5 5 5M3 9h11a6 6 0 0 1 0 12', reset:'M3 11a9 9 0 1 1 2 7M3 3v8h8',
  plus:'M12 4v16M4 12h16', settings:'M4 5h16M4 12h16M4 19h16M8 2v6M16 9v6M10 16v6',
  arrow:'M4 12h16m-6-6 6 6-6 6', clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0', filter:'M3 5h18M6 12h12M9 19h6',
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.info}"/></svg>`;
const hydrateIcons = () => $$('[data-icon]').forEach(el => { el.innerHTML = icon(el.dataset.icon); });
const pages = [
  {id:'analysis',label:'结果分析',short:'分析',icon:'chart',tab:'攻击力扫描结果'},
  {id:'parameters',label:'参数编辑',short:'参数',icon:'table',tab:'候选方案 A'},
  {id:'designer',label:'实验设计',short:'实验',icon:'flask',tab:'初始攻击力扫描'},
  {id:'runs',label:'运行任务',short:'任务',icon:'terminal',tab:'任务队列'},
  {id:'exchange',label:'数据与导出',short:'数据',icon:'exchange',tab:'数据交换'},
];
const metrics = {
  win: {label:'战斗胜率',id:'win_rate',unit:'%',min:50,max:80,target:65,op:'≥',base:64.3,ci:.8,decimals:1},
  retention: {label:'D7 留存率',id:'retention_d7',unit:'%',min:34,max:52,target:42,op:'≥',base:40.7,ci:.6,decimals:1},
  gold: {label:'人均金币产出',id:'gold_per_player',unit:'',min:1500,max:2900,target:2400,op:'≤',base:2084,ci:55,decimals:0},
};
const candidates = [
  [80,54.2,36.8,1680],[85,56.8,37.6,1760],[90,59.7,38.9,1860],[95,62.1,39.7,1970],
  [100,64.3,40.7,2084],[105,66.1,42.1,2180],[110,68.4,44.6,2280],[115,69.5,45.2,2380],
  [120,70.9,46.1,2480],[125,71.7,46.7,2580],[130,72.3,47.1,2690],
].map(([attack,win,retention,gold],i)=>({id:`C-${String(i+1).padStart(3,'0')}`,attack,win,retention,gold,replicates:20}));
// ID, kind, default, description match the repository's registry.rs. Group names are UI organization.
const paramDefinitions = [
  ['model.warrior.attack','i64',100,'初始攻击力','角色'],['model.warrior.defense','i64',80,'初始防御','角色'],
  ['model.warrior.hp','i64',1000,'初始生命','角色'],['model.combat.p_hit','f64',.85,'玩家命中概率','战斗'],
  ['model.combat.p_hit_monster','f64',.85,'怪物命中概率','战斗'],['model.combat.dmg_var','i64',10,'伤害浮动半宽','战斗'],
  ['model.combat.max_rounds','u32',32,'最大战斗轮数','战斗'],['model.dungeon.m_hp','i64',300,'第 0 层怪物生命','副本'],
  ['model.dungeon.m_attack','i64',45,'第 0 层怪物攻击','副本'],['model.dungeon.m_defense','i64',20,'第 0 层怪物防御','副本'],
  ['model.dungeon.tier_growth','f64',1.5,'每层怪物数值倍率','副本'],['model.dungeon.reward_gold','i64',40,'第 0 层金币产出','副本'],
  ['model.dungeon.reward_xp','i64',45,'第 0 层经验产出','副本'],['model.progression.xp_base','i64',60,'升级经验基数','成长'],
  ['model.progression.xp_pow','f64',1.3,'升级经验指数','成长'],['model.churn.p_base','f64',.003,'正常日流失概率','流失'],
  ['model.churn.p_stall','f64',.05,'停滞日流失概率','流失'],['model.churn.stall_days','u32',2,'连续无增长天数判停滞','流失'],
].map(([id,type,base,name,group])=>({id,type,base,name,group}));
const defaults = Object.fromEntries(paramDefinitions.map(p=>[p.id,p.base]));
const storageKey = 'sandtable-workbench-v2';
let persisted = {};
try { persisted = JSON.parse(localStorage.getItem(storageKey) || '{}'); } catch { /* A corrupt draft must not prevent opening the prototype. */ }
const restoredValues = {...defaults,'model.warrior.attack':110,'model.combat.p_hit':.88};
for (const p of paramDefinitions) if (persisted.values && typeof persisted.values[p.id]==='number' && Number.isFinite(persisted.values[p.id])) restoredValues[p.id] = persisted.values[p.id];
const state = {
  page: pages.some(p=>p.id===location.hash.slice(1)) ? location.hash.slice(1) : 'analysis',
  selected: 'C-007',metric:'win',resultView:'chart',resultFilter:'all',sort:'attack',sortDir:1,inspector:true,
  values:restoredValues,paramSearch:'',paramGroup:'all',changedOnly:false,paramSelected:new Set(),paramFocus:'model.warrior.attack',
  history:[],saved:true,method:'grid',design:{name:'初始攻击力扫描',min:80,max:130,step:5,samples:24,reps:20,players:10000,days:30,paired:true,sampling:'lhs',win:65,retention:42,gold:2400},
  jobs:[],drawer:false,exportFormat:'csv',exportScope:'all',
};
let toastTimer;
function notify(message) { const el=$('#toast'); el.textContent=message; el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3400); }
function persist() {
  try {localStorage.setItem(storageKey,JSON.stringify({values:state.values}));state.saved=true;updateSaveState();notify('候选方案已保存到当前浏览器');}
  catch {notify('浏览器存储不可用，草稿仍保留在当前页面');}
}
function markDirty() {state.saved=false;updateSaveState();}
function updateSaveState(){ const el=$('#save-state');if(el)el.textContent=state.saved?'浏览器草稿已保存':'存在未保存修改';const count=changedParams().length;$('#explorer-changes').textContent=`${count} 项参数变更`;const tab=$('#tab-parameters');if(tab){const dot=$('.document-dot',tab);if(state.saved)dot?.remove();else if(!dot)tab.insertAdjacentHTML('beforeend','<span class="document-dot"></span>');} }
const selectedCandidate = () => candidates.find(c=>c.id===state.selected) || candidates[6];
const changedParams = () => paramDefinitions.filter(p=>Number(state.values[p.id])!==p.base);
function verdictFor(c,key) {const m=metrics[key],value=c[key]; if(m.op==='≥') return value-m.ci>=m.target?'pass':value+m.ci>=m.target?'border':'fail';return value+m.ci<=m.target?'pass':value-m.ci<=m.target?'border':'fail';}
function verdict(c) {const vs=Object.keys(metrics).map(k=>verdictFor(c,k));return vs.includes('fail')?'fail':vs.includes('border')?'border':'pass';}
const verdictLabel = v => ({pass:'通过',border:'临界',fail:'未通过'}[v]);
const verdictHtml = v => `<span class="verdict ${v}">${icon(v==='pass'?'circlecheck':v==='border'?'warning':'cross')}${verdictLabel(v)}</span>`;
const fmt=(value,key)=>Number(value).toFixed(metrics[key].decimals)+(metrics[key].unit||'');
const ciText=(c,key)=>`[${(c[key]-metrics[key].ci).toFixed(metrics[key].decimals)}, ${(c[key]+metrics[key].ci).toFixed(metrics[key].decimals)}]`;
function filteredCandidates(){let rows=candidates.filter(c=>state.resultFilter==='all'||verdict(c)===state.resultFilter);return [...rows].sort((a,b)=>{const av=state.sort==='verdict'?({pass:0,border:1,fail:2}[verdict(a)]):a[state.sort];const bv=state.sort==='verdict'?({pass:0,border:1,fail:2}[verdict(b)]):b[state.sort];return (av>bv?1:av<bv?-1:0)*state.sortDir;});}
function heading(title,crumb,actions='',suffix=''){return `<header class="workspace-heading"><div><div class="breadcrumb">RPG 平衡实验室<span>/</span>${crumb}</div><h1>${title}${suffix}</h1></div><div class="actions">${actions}</div></header>`;}
const btn=(label,action,ico,classes='')=>`<button class="btn ${classes}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
function renderShell(){
  $('#activity-rail').innerHTML=pages.map(p=>`<button class="rail-button ${p.id===state.page?'active':''}" data-page="${p.id}" title="${p.label}" aria-label="${p.label}" ${p.id===state.page?'aria-current="page"':''}>${icon(p.icon)}<span>${p.short}</span></button>`).join('')+`<button class="rail-button rail-bottom" data-action="shortcuts" title="快捷键" aria-label="快捷键">${icon('settings')}</button>`;
  $('#document-tabs').innerHTML=pages.slice(0,3).map(p=>`<button class="document-tab ${p.id===state.page?'active':''}" role="tab" id="tab-${p.id}" aria-selected="${p.id===state.page}" tabindex="${p.id===state.page?0:-1}" data-page="${p.id}" aria-controls="workspace">${icon(p.icon)}${p.tab}${p.id==='parameters'&&!state.saved?'<span class="document-dot"></span>':''}</button>`).join('')+(state.page==='runs'||state.page==='exchange'?`<button class="document-tab active" role="tab" data-page="${state.page}" id="tab-${state.page}" aria-controls="workspace" aria-selected="true">${icon(pages.find(p=>p.id===state.page).icon)}${pages.find(p=>p.id===state.page).tab}</button>`:'');
  $$('.resource').forEach(el=>el.classList.toggle('selected',el.dataset.page===state.page));
}
function navigate(page){if(!pages.some(p=>p.id===page))return;state.page=page;history.replaceState(null,'',`#${page}`);render();$('#workspace').focus({preventScroll:true});}
function render(){renderShell();const renderers={analysis:renderAnalysis,parameters:renderParameters,designer:renderDesigner,runs:renderRuns,exchange:renderExchange};$('#workspace').innerHTML=renderers[state.page]();$('#workspace').setAttribute('role','tabpanel');$('#workspace').setAttribute('aria-labelledby',`tab-${state.page}`);hydrateIcons();renderDrawer();updateSaveState();if(state.page==='analysis'){const row=$('.candidate-row.selected'),table=$('.candidate-table-wrap');if(row&&table)table.scrollTop+=row.getBoundingClientRect().top-table.getBoundingClientRect().top-table.clientHeight/2+17;}}

function chart(key,mini=false){
  const m=metrics[key],c=selectedCandidate();
  const narrow=innerWidth<=760,inspectorWidth=innerWidth>=1700?298:innerWidth<=1060?236:innerWidth<=1250?232:267;
  const centerWidth=($('#workspace').clientWidth||1100)-(state.inspector&&!narrow?inspectorWidth:0);
  const W=mini?Math.max(260,narrow?centerWidth-26:(centerWidth-42)/2-14):Math.max(narrow?580:420,centerWidth-(innerWidth<=1250?32:42));
  const H=mini?86:narrow?192:innerWidth>=1700?315:235;
  const left=mini?35:49,right=mini?13:22,top=mini?9:28,bottom=mini?18:48;
  const x=v=>left+(v-80)/50*(W-left-right),y=v=>top+(m.max-v)/(m.max-m.min)*(H-top-bottom);
  const ticks=mini?2:6;
  let out=`<svg class="${mini?'mini-chart':'main-chart'}" id="chart-${key}" viewBox="0 0 ${W} ${H}" role="group" aria-label="${m.label}随初始攻击力变化，11 个离散样例候选及其 95% 置信区间"><title>${m.label}参数响应图，内置演示数据</title>`;
  out+=`<rect x="${left}" y="${m.op==='≥'?top:y(m.target)}" width="${W-left-right}" height="${m.op==='≥'?y(m.target)-top:H-bottom-y(m.target)}" fill="#eff7f5"/>`;
  for(let i=0;i<=ticks;i++){const val=m.min+(m.max-m.min)*i/ticks;out+=`<line x1="${left}" x2="${W-right}" y1="${y(val)}" y2="${y(val)}" class="chart-grid"/><text x="${left-9}" y="${y(val)+4}" text-anchor="end" class="chart-text" style="font-size:${mini?9:11}px">${val.toFixed(0)}${m.unit}</text>`;}
  for(const v of [80,90,100,110,120,130]){out+=`<text x="${x(v)}" y="${H-bottom+17}" text-anchor="middle" class="chart-text" style="font-size:${mini?9:11}px">${v}</text>`;if(!mini)out+=`<line x1="${x(v)}" x2="${x(v)}" y1="${top}" y2="${H-bottom}" stroke="#f0f4f5"/>`;}
  out+=`<line x1="${left}" x2="${W-right}" y1="${y(m.target)}" y2="${y(m.target)}" stroke="#b48d49" stroke-width="1" stroke-dasharray="4 4"/>`;
  if(!mini){out+=`<text x="${W-right-3}" y="${y(m.target)-7}" text-anchor="end" style="fill:#98713a;font:10px sans-serif">约束 ${m.op} ${m.target}${m.unit}</text><line x1="${left}" x2="${W-right}" y1="${y(m.base)}" y2="${y(m.base)}" stroke="#b6c5ce" stroke-dasharray="2 4"/><text x="${left}" y="14" class="chart-label">${m.id}${m.unit?' / '+m.unit:''}</text>`;}
  out+=`<rect x="${x(c.attack)-(mini?8:13)}" y="${top}" width="${mini?16:26}" height="${H-top-bottom}" fill="#bc8b2210"/><line x1="${x(c.attack)}" x2="${x(c.attack)}" y1="${top}" y2="${H-bottom}" stroke="#c9ad7c" stroke-dasharray="3 4"/>`;
  for(const row of candidates){const selected=row.id===state.selected;out+=`<g class="chart-candidate ${selected?'selected':''}" role="button" tabindex="0" data-candidate="${row.id}" aria-label="${row.id}，攻击力 ${row.attack}，${m.label} ${fmt(row[key],key)}，95% CI ${ciText(row,key)}" aria-pressed="${selected}"><title>${row.id} · attack ${row.attack}\n${m.label} ${fmt(row[key],key)}\n95% CI ${ciText(row,key)}\n${verdictLabel(verdict(row))}</title><rect x="${x(row.attack)-10}" y="${y(row[key]+m.ci)-8}" width="20" height="${Math.max(24,y(row[key]-m.ci)-y(row[key]+m.ci)+16)}" fill="transparent"/><path class="chart-ci" d="M${x(row.attack)} ${y(row[key]+m.ci)}V${y(row[key]-m.ci)}M${x(row.attack)-3} ${y(row[key]+m.ci)}h6M${x(row.attack)-3} ${y(row[key]-m.ci)}h6"/><circle class="chart-point" cx="${x(row.attack)}" cy="${y(row[key])}" r="${mini?selected?4:2.6:selected?6:4}"/></g>`;}
  if(!mini){const px=Math.min(W-140,Math.max(left+5,x(c.attack)+15));const py=Math.max(top+7,y(c[key])-53);out+=`<g pointer-events="none"><rect x="${px}" y="${py}" width="117" height="39" rx="3" fill="#fff" stroke="#c4d7da"/><text x="${px+9}" y="${py+14}" style="fill:#647b85;font:10px monospace">${c.id} · ATK ${c.attack}</text><text x="${px+9}" y="${py+29}" style="fill:#176f73;font:600 13px monospace">${fmt(c[key],key)}</text></g><text x="${(W+left-right)/2}" y="${H-6}" text-anchor="middle" class="chart-label">初始攻击力 · model.warrior.attack</text>`;}
  return out+'</svg>';
}
function candidateTable(expanded=false){const rows=filteredCandidates();return `<div class="candidate-table-wrap"${expanded?' style="max-height:none"':''}><table class="candidate-table" aria-label="参数扫描候选结果"><thead><tr><th>候选 / 对照</th>${[['attack','初始攻击力'],['win','战斗胜率'],['retention','D7 留存率'],['gold','人均金币产出']].map(([id,label])=>`<th class="numeric" aria-sort="${state.sort===id?state.sortDir===1?'ascending':'descending':'none'}"><button class="sort-button" data-sort="${id}">${label}<span>${state.sort===id?(state.sortDir===1?'↑':'↓'):'↕'}</span></button></th>`).join('')}${expanded?'<th>胜率 95% CI</th>':''}<th><button class="sort-button" data-sort="verdict">约束判定 ↕</button></th></tr></thead><tbody>${rows.map(c=>`<tr class="candidate-row ${c.id===state.selected?'selected':''}" data-candidate="${c.id}" aria-selected="${c.id===state.selected}"><td><div class="table-id"><button class="candidate-select" data-candidate="${c.id}" aria-label="选择候选 ${c.id}">${c.id}</button>${c.attack===100?'<span class="badge">基线</span>':''}</div></td><td class="numeric">${c.attack}</td><td class="numeric">${fmt(c.win,'win')}</td><td class="numeric">${fmt(c.retention,'retention')}</td><td class="numeric">${fmt(c.gold,'gold')}</td>${expanded?`<td class="mono">${ciText(c,'win')}</td>`:''}<td>${verdictHtml(verdict(c))}</td></tr>`).join('')||'<tr><td colspan="7"><div class="empty-state">当前筛选没有候选。选择“全部候选”可恢复显示。</div></td></tr>'}</tbody></table></div>`;}
function candidateInspector(){const c=selectedCandidate();return `<aside class="selection-inspector" aria-label="所选候选详情"><div class="inspector-header">${icon('sliders')}选择检查器<button class="icon-button" data-action="toggle-inspector" aria-label="收起选择检查器" title="收起检查器">${icon('panel-right')}</button></div><section class="inspector-section"><div class="inspector-eyebrow">SELECTED CANDIDATE</div><div class="inspector-title">${c.id}${verdictHtml(verdict(c))}</div><span class="inspector-code">model.warrior.attack</span><div class="parameter-value">${c.attack}<small>基线 100 · ${c.attack>=100?'+':''}${c.attack-100}%</small></div><button class="btn inspector-action" data-action="adopt">${icon('copy')}复制参数到候选方案 A</button></section><section class="inspector-section"><h3>硬约束 · 95% CI 判定</h3>${Object.entries(metrics).map(([key,m])=>{const v=verdictFor(c,key);return `<div class="constraint-row"><div><span>${m.label}</span>${verdictHtml(v)}</div><div class="constraint-values"><span>${fmt(c[key],key)}</span><span>${m.op} ${m.target}${m.unit}</span></div><div class="constraint-bar ${v}"><span style="width:${Math.min(100,Math.max(10,(c[key]-m.min)/(m.max-m.min)*100))}%"></span></div><div class="constraint-values"><span>95% CI</span><span>${ciText(c,key)}</span></div></div>`;}).join('')}</section><section class="inspector-section"><h3>统计口径</h3><div class="inspector-kv"><span>方法</span><span>Grid / 离散观测</span></div><div class="inspector-kv"><span>统计单位</span><span class="mono">20 replicates</span></div><div class="inspector-kv"><span>场景规模</span><span>10,000 玩家 × 30 天</span></div><div class="inspector-kv"><span>数据来源</span><span class="badge amber">内置合成样例</span></div><p class="note">CI 完全满足阈值才判“通过”；区间与边界相交判“临界”。图中点之间不做插值。</p></section><section class="inspector-section"><h3>后续操作</h3><button class="btn" style="width:100%" data-action="candidate-export">${icon('download')}导出所选候选</button><p class="note" style="margin-top:9px">复制参数后可在编辑器修改，再新建实验。样例结果保持原始快照。</p></section></aside>`;}
function renderAnalysis(){const c=selectedCandidate(),m=metrics[state.metric],others=Object.keys(metrics).filter(k=>k!==state.metric);return heading('初始攻击力扫描','结果集 / Grid 单参数',btn('调整实验','edit-experiment','flask')+btn('导出','export-dialog','download','primary'),'<span class="badge teal">GRID</span>')+`<div class="workspace-toolbar"><div class="segmented" aria-label="结果显示方式"><button data-view="chart" class="${state.resultView==='chart'?'active':''}" aria-pressed="${state.resultView==='chart'}">${icon('chart')}响应图</button><button data-view="table" class="${state.resultView==='table'?'active':''}" aria-pressed="${state.resultView==='table'}">${icon('table')}数据表</button></div><span class="divider"></span><label class="toolbar-label" for="metric-select">主指标</label><select id="metric-select" aria-label="主图指标">${Object.entries(metrics).map(([key,m])=>`<option value="${key}" ${state.metric===key?'selected':''}>${m.label}</option>`).join('')}</select><div class="toolbar-end"><span class="muted" style="font-size:10px">11 候选 · 20 replicates / 候选</span><button class="icon-button" data-action="toggle-inspector" aria-label="${state.inspector?'收起':'显示'}选择检查器" title="切换选择检查器">${icon('panel-right')}</button></div></div><div class="analysis-body ${state.inspector?'':'inspector-hidden'}"><div class="analysis-center">${state.resultView==='chart'?`<section class="figure-section"><div class="section-heading"><div><h2>参数响应 · ${m.label}</h2><div class="figure-subtitle">单参数观测点与 95% CI <span class="muted">/</span> 选点查看候选</div></div><div class="legend"><span><i class="legend-dot"></i>候选均值</span><span><i class="legend-ci"></i>95% CI</span><span><i class="legend-line"></i>目标边界</span></div></div><div class="chart-viewport">${chart(state.metric)}</div><div class="chart-footer"><span>浅绿区域：当前指标的目标范围　·　虚线：约束 / 基线</span><span>离散采样 · 无插值</span></div><div class="mini-figures">${others.map(key=>`<div class="mini-figure"><div class="mini-figure-header"><strong>${metrics[key].label}</strong><span class="mono">${c.id} · ${fmt(c[key],key)}</span></div>${chart(key,true)}</div>`).join('')}</div></section>`:''}<section class="candidate-section"><div class="section-heading"><h2>候选结果<span class="badge">${filteredCandidates().length} / 11</span></h2><div class="actions"><select id="result-filter" aria-label="按约束判定筛选">${[['all','全部候选'],['pass','仅通过'],['border','仅临界'],['fail','仅未通过']].map(([v,l])=>`<option value="${v}" ${state.resultFilter===v?'selected':''}>${l}</option>`).join('')}</select><button class="icon-button" data-action="export-csv" aria-label="导出当前筛选的候选 CSV" title="导出当前筛选 CSV">${icon('download')}</button></div></div>${candidateTable(state.resultView==='table')}<div class="table-foot"><span>✓ 1 通过　△ 2 临界　× 8 未通过</span><span>↑ ↓ 选择候选 · Enter 查看</span></div></section></div>${candidateInspector()}</div>`;}

function visibleParams(){const q=state.paramSearch.trim().toLowerCase();return paramDefinitions.filter(p=>(!q||`${p.id} ${p.name}`.toLowerCase().includes(q))&&(state.paramGroup==='all'||p.group===state.paramGroup)&&(!state.changedOnly||state.values[p.id]!==p.base));}
function validateParam(p,value){if(!Number.isFinite(value))return '请输入有限数值';if(p.type!=='f64'&&!Number.isSafeInteger(value))return '需要安全范围内的整数';if(p.type==='u32'&&(value<0||value>4294967295))return '范围为 0–4294967295';if(p.id.includes('.p_')&&(value<0||value>1))return '概率范围为 0–1';return '';}
function parameterRows(){const rows=visibleParams();return rows.map(p=>{const value=state.values[p.id],changed=value!==p.base;return `<tr class="${state.paramFocus===p.id?'selected':''}" data-param-row="${p.id}"><td><input class="checkbox" type="checkbox" data-param-check="${p.id}" ${state.paramSelected.has(p.id)?'checked':''} aria-label="选择${p.name}"/></td><td><button style="padding:0;text-align:left" data-param-focus="${p.id}"><span class="parameter-name">${p.name}</span><span class="parameter-path">${p.id}</span></button></td><td class="mono muted" style="font-size:10px">${p.type}</td><td class="numeric muted">${p.base}</td><td class="numeric"><input class="cell-value ${changed?'changed':''}" type="number" step="${p.type==='f64'?'any':'1'}" value="${value}" data-param-value="${p.id}" aria-label="${p.name}候选值"/><span class="parameter-error" id="error-${p.id.replaceAll('.','-')}" aria-live="polite"></span></td><td class="numeric ${changed?'positive':'muted'}">${changed?`${value>p.base?'+':''}${((value-p.base)/Math.abs(p.base)*100).toFixed(1)}%`:'—'}</td><td>${changed?'<span class="badge amber">已修改</span>':'<span class="muted">—</span>'}</td></tr>`;}).join('')||'<tr><td colspan="7"><div class="empty-state">没有匹配的参数。尝试清空搜索或切换系统分组。</div></td></tr>';}
function parameterInspector(){const p=paramDefinitions.find(p=>p.id===state.paramFocus)||paramDefinitions[0];return `<aside class="selection-inspector" aria-label="参数详情"><div class="inspector-header">${icon('sliders')}参数检查器</div><section class="inspector-section"><div class="inspector-eyebrow">${p.group.toUpperCase()} / PARAMETER</div><div class="inspector-title">${p.name}</div><code class="inspector-code">${p.id}</code><div class="parameter-value">${state.values[p.id]}<small>候选值</small></div><div class="inspector-kv"><span>基线默认值</span><span class="mono">${p.base}</span></div><div class="inspector-kv"><span>数据类型</span><span class="mono">${p.type}</span></div><button class="btn inspector-action" data-action="reset-single">${icon('reset')}恢复此项基线值</button></section><section class="inspector-section"><h3>定义与校验</h3><p class="note">${p.name}。路径、类型和基线值取自 Sandtable 参数注册表。</p><div class="inspector-kv"><span>单位元数据</span><span class="muted">未定义</span></div><div class="inspector-kv"><span>建议区间元数据</span><span class="muted">未定义</span></div><div class="inspector-kv"><span>注册表来源</span><span class="mono">registry.rs</span></div><div class="note-block" style="margin-top:12px">原型只检查数值类型${p.id.includes('.p_')?'及概率范围':''}。完整配置有效性与跨参数关系需要内核校验。</div></section><section class="inspector-section"><h3>方案修改摘要</h3><div class="inspector-kv"><span>相对默认基线</span><span>${changedParams().length} 项变更</span></div><div class="inspector-kv"><span>保存位置</span><span>当前浏览器</span></div><p class="note">修改参数不会重算内置样例结果。完成配置后，可在实验设计器设置新的比较方式。</p><button class="btn inspector-action primary" data-page="designer">${icon('flask')}配置新实验</button></section></aside>`;}
function renderParameters(){return heading('候选方案 A','模型与配置 / 参数表',`<span class="muted" id="save-state" style="font-size:10px"></span>`+btn('撤销','undo','undo')+btn('保存草稿','save','save','primary'),'<span class="badge amber">本地草稿</span>')+`<div class="workspace-toolbar"><label class="search-field">${icon('search')}<input id="parameter-search" type="search" placeholder="搜索名称或参数路径" value="${esc(state.paramSearch)}" aria-label="搜索参数"/></label><select id="parameter-group" aria-label="按系统分组筛选"><option value="all">全部系统</option>${['角色','战斗','副本','成长','流失'].map(g=>`<option ${state.paramGroup===g?'selected':''}>${g}</option>`).join('')}</select><label class="checkbox-line" style="margin:0"><input class="checkbox" id="changed-only" type="checkbox" ${state.changedOnly?'checked':''}/>仅变更 <span class="mono">${changedParams().length}</span></label><div class="toolbar-end">${btn('恢复全部','reset-all','reset','subtle')}</div></div>${state.paramSelected.size?`<div class="bulk-bar"><strong>已选 ${state.paramSelected.size} 项</strong><span>候选值 ×</span><input id="bulk-factor" type="number" value="1.1" step="0.1" aria-label="批量修改倍率"/>${btn('应用倍率','bulk-multiply',null)}${btn('取消选择','clear-selection',null,'subtle')}<span class="muted">整数参数自动四舍五入</span></div>`:''}<div class="parameters-body"><div class="parameters-center"><table class="parameter-table" aria-label="候选方案参数编辑表"><thead><tr><th><input id="all-params" class="checkbox" type="checkbox" aria-label="选择当前可见参数" ${visibleParams().length&&visibleParams().every(p=>state.paramSelected.has(p.id))?'checked':''}/></th><th>参数名称 / 注册路径</th><th>类型</th><th class="numeric">基线</th><th class="numeric">候选值</th><th class="numeric">相对变化</th><th>状态</th></tr></thead><tbody id="parameter-rows">${parameterRows()}</tbody></table><div class="table-foot"><span id="parameter-count">${visibleParams().length} / ${paramDefinitions.length} 个示例参数</span><span>基线只读 · 候选值可编辑</span></div></div>${parameterInspector()}</div>`;}
function updateParameterFilter(){const rows=$('#parameter-rows');if(rows)rows.innerHTML=parameterRows();const count=$('#parameter-count');if(count)count.textContent=`${visibleParams().length} / ${paramDefinitions.length} 个示例参数`;const all=$('#all-params');if(all)all.checked=visibleParams().length>0&&visibleParams().every(p=>state.paramSelected.has(p.id));}
function commitParam(id,value,input){const p=paramDefinitions.find(p=>p.id===id),error=validateParam(p,value);if(error){input?.classList.add('invalid');const e=$(`#error-${id.replaceAll('.','-')}`);if(e)e.textContent=error;notify(`${p.name}：${error}`);return false;}if(state.values[id]!==value){state.history.push({...state.values});state.values[id]=value;state.paramFocus=id;markDirty();}if(input){
  // Preserve the click target when change fires during a blur (e.g. clicking Save).
  input.classList.remove('invalid');input.classList.toggle('changed',value!==p.base);
  const row=input.closest('tr');row.cells[5].textContent=value===p.base?'—':`${value>p.base?'+':''}${((value-p.base)/Math.abs(p.base)*100).toFixed(1)}%`;row.cells[6].innerHTML=value===p.base?'<span class="muted">—</span>':'<span class="badge amber">已修改</span>';
  const err=$(`#error-${id.replaceAll('.','-')}`);if(err)err.textContent='';
  const display=$('.parameters-body .parameter-value');if(display)display.innerHTML=`${value}<small>候选值</small>`;
}else render();return true;}

function designCounts(){const d=state.design;let count=state.method==='ab'?2:state.method==='grid'?(d.step>0&&d.max>=d.min?Math.floor((d.max-d.min)/d.step+1e-9)+1:0):d.samples;return {candidates:count,tasks:count*d.reps,playerDays:count*d.reps*d.players*d.days};}
function designErrors(){const d=state.design,e=[];if(!d.name.trim())e.push('请填写实验名称');for(const [key,label] of [['reps','replicates'],['players','玩家数'],['days','仿真天数']])if(!Number.isSafeInteger(d[key])||d[key]<=0)e.push(`${label}需为正整数`);if(d.days<7)e.push('D7 留存要求仿真周期至少 7 天');if(state.method!=='ab'&&(!Number.isSafeInteger(d.min)||!Number.isSafeInteger(d.max)||d.min<=0||d.max<d.min))e.push('攻击力范围需要正整数，且最大值不小于最小值');if(state.method==='grid'&&(!Number.isSafeInteger(d.step)||d.step<=0))e.push('Grid 步长需要正整数');if(state.method==='random'&&(!Number.isSafeInteger(d.samples)||d.samples<=0))e.push('采样数需要正整数');for(const key of ['win','retention'])if(!Number.isFinite(d[key])||d[key]<0||d[key]>100)e.push(`${metrics[key].label}阈值需在 0–100 之间`);if(!Number.isFinite(d.gold)||d.gold<0)e.push('金币阈值需为非负数');if(designCounts().tasks>100000)e.push('原型单次任务预算上限为 100,000，请缩小实验规模');return e;}
function designSummary(){const d=state.design,c=designCounts(),errors=designErrors(),method=state.method==='ab'?'A/B':state.method==='grid'?'Grid':'Random / LHS';return `<h3>运行计划</h3><div class="budget-value">${Number.isFinite(c.tasks)?c.tasks.toLocaleString():'—'}</div><div class="budget-caption">次单方案运行 · 演示任务</div><div class="summary-formula">${c.candidates} 个${state.method==='ab'?'方案':'候选'} × ${d.reps} replicates</div><div class="inspector-kv"><span>实验方法</span><span>${method}</span></div><div class="inspector-kv"><span>每次运行</span><span>${d.players.toLocaleString()} 玩家 / ${d.days} 天</span></div><div class="inspector-kv"><span>总 player-days</span><span class="mono">${Number.isFinite(c.playerDays)?c.playerDays.toLocaleString():'—'}</span></div><div class="inspector-kv"><span>耗时估算</span><span class="muted">尚无性能基准</span></div><div class="preflight"><h3>运行前基础校验</h3>${errors.length?errors.map(e=>`<div class="check-row error">${icon('warning')}<span>${e}</span></div>`).join(''):`<div class="check-row">${icon('circlecheck')}<span>因子范围与类型有效</span></div><div class="check-row">${icon('circlecheck')}<span>D7 指标满足运行天数要求</span></div><div class="check-row">${icon('circlecheck')}<span>任务数在演示预算内</span></div>`}<div class="check-row info">${icon('info')}<span>完整 schema、公式、资源检查由实际内核接入后提供。</span></div></div><button class="btn primary" data-action="enqueue" ${errors.length?'disabled':''}>${icon('play')}加入演示队列</button><p class="note" style="margin-top:11px">用于体验进度与取消流程。演示任务不执行仿真，不生成新的统计结果。</p>`;}
function designField(id,label,value,type='number',helper=''){return `<div class="field"><label for="design-${id}">${label}</label><input id="design-${id}" data-design="${id}" type="${type}" value="${esc(value)}" ${type==='number'?'step="any"':''}/>${helper?`<small>${helper}</small>`:''}</div>`;}
function renderDesigner(){const d=state.design;return heading('实验设计','实验 / 新建运行',btn('查看结果样例','show-analysis','chart'),'<span class="badge">DRAFT</span>')+`<div class="form-layout"><div class="form-main"><section class="form-section"><div class="form-section-heading"><span class="step">01</span><h2>比较对象与实验方法</h2></div><div class="field" style="margin-bottom:15px"><label for="design-name">实验名称</label><input id="design-name" data-design="name" value="${esc(d.name)}" style="width:100%"/></div><div class="method-options">${[['ab','A/B 配对比较','基线 vs 候选方案'],['grid','Grid 参数扫描','等距枚举 · 精确比较'],['random','Random / LHS','固定预算 · 空间采样']].map(([id,label,desc])=>`<button class="method-option ${state.method===id?'active':''}" data-method="${id}" aria-pressed="${state.method===id}"><strong>${label}${state.method===id?icon('circlecheck'):''}</strong><small>${desc}</small></button>`).join('')}</div></section><section class="form-section"><div class="form-section-heading"><span class="step">02</span><h2>${state.method==='ab'?'方案参数差异':'实验因子与取值域'}</h2></div>${state.method==='ab'?`<div class="note-block">对照：注册表默认基线　→　候选：方案 A。${changedParams().length} 项变更。</div><div style="overflow:auto"><table style="margin-top:10px"><thead><tr><th>参数路径</th><th class="numeric">基线</th><th class="numeric">候选 A</th></tr></thead><tbody>${changedParams().map(p=>`<tr><td class="mono" style="font-size:11px">${p.id}</td><td class="numeric">${p.base}</td><td class="numeric positive">${state.values[p.id]}</td></tr>`).join('')||'<tr><td colspan="3">当前候选没有参数差异，可先前往参数编辑器修改。</td></tr>'}</tbody></table></div>`:`<div class="factor-grid"><span>因子 / 参数路径</span><label class="muted" for="design-min" style="font-size:10px">最小值</label><label class="muted" for="design-max" style="font-size:10px">最大值</label><label class="muted" for="design-${state.method==='grid'?'step':'samples'}" style="font-size:10px">${state.method==='grid'?'步长':'采样数'}</label><div class="factor-name">model.warrior.attack<br><span style="color:#82939a">i64 · 初始攻击力</span></div><input id="design-min" data-design="min" type="number" value="${d.min}"/><input id="design-max" data-design="max" type="number" value="${d.max}"/><input id="design-${state.method==='grid'?'step':'samples'}" data-design="${state.method==='grid'?'step':'samples'}" type="number" value="${state.method==='grid'?d.step:d.samples}"/></div>${state.method==='random'?`<div class="field" style="margin-top:14px"><label for="sampling-method">采样方式</label><select id="sampling-method" data-design="sampling"><option value="lhs" ${d.sampling==='lhs'?'selected':''}>Latin Hypercube · 拉丁超立方</option><option value="random" ${d.sampling==='random'?'selected':''}>Random · 独立均匀随机</option></select><small>原型展示单因子配置；多因子矩阵与去重策略待正式实现。</small></div>`:''}`}</section><section class="form-section"><div class="form-section-heading"><span class="step">03</span><h2>场景规模与随机策略</h2></div><div class="form-grid">${designField('players','每次运行玩家数',d.players,'number','场景规模，不等于统计样本量')}${designField('days','仿真天数',d.days,'number','D7 指标要求 ≥ 7 天')}${designField('reps','Replicates / 候选',d.reps,'number','统计单位为独立 replicate')}<div class="field"><label for="seed-display">基础随机种子</label><input id="seed-display" value="12345" readonly class="mono"/><small>演示固定值；正式实验应纳入快照</small></div></div><label class="checkbox-line"><input class="checkbox" id="paired-random" type="checkbox" ${d.paired?'checked':''}/>方案间共享随机键（CRN）<span class="badge teal">建议</span></label></section><section class="form-section"><div class="form-section-heading"><span class="step">04</span><h2>观察指标与硬约束</h2></div><div style="overflow:auto"><table class="constraint-table"><thead><tr><th>指标 / 口径</th><th>目标</th><th class="numeric">阈值</th><th>统计判定</th></tr></thead><tbody>${Object.entries(metrics).map(([key,m])=>`<tr><td>${m.label}<span class="parameter-path" style="display:block;font:10px var(--mono);color:var(--muted)">${m.id}</span></td><td class="mono">${m.op}</td><td class="numeric"><label><input data-design="${key}" aria-label="${m.label}目标阈值" type="number" value="${d[key]}" step="any"/>${m.unit}</label></td><td><span class="badge">95% CI</span></td></tr>`).join('')}</tbody></table></div><p class="note" style="margin-top:10px">胜率与金币指标覆盖全程，留存指标取 D7。不同单位分别判定；整体可行需同时满足全部硬约束。</p></section></div><aside class="form-summary" id="design-summary" aria-label="运行计划与校验">${designSummary()}</aside></div>`;}

function taskItem(job){return `<div class="task-item"><div><strong>${esc(job.name)}</strong><small>${job.status} · 演示任务 · 不执行内核</small></div><div class="task-progress" role="progressbar" aria-label="${esc(job.name)}进度" aria-valuenow="${job.done}" aria-valuemin="0" aria-valuemax="${job.total}"><span style="width:${job.done/job.total*100}%"></span></div><span class="mono">${job.done} / ${job.total}</span>${job.status==='运行中'?`<button class="btn" data-cancel-job="${job.id}" style="min-height:26px;font-size:10px">取消</button>`:''}</div>`;}
function renderDrawer(){const el=$('#task-drawer');el.hidden=!state.drawer;el.innerHTML=`<div class="drawer-heading"><strong>${icon('terminal')}任务队列<span class="badge amber">演示模式</span></strong><div class="actions">${btn('全部任务','all-jobs',null,'subtle')}<button class="icon-button" data-action="toggle-tasks" aria-label="收起任务队列">${icon('cross')}</button></div></div>${state.jobs.length?state.jobs.slice(-2).reverse().map(taskItem).join(''):'<div class="empty-state" style="padding:22px">暂无演示任务。在实验设计器配置后加入队列。</div>'}`;const running=state.jobs.filter(j=>j.status==='运行中').length;$('#task-status').innerHTML=`${icon('terminal')}${running?'演示运行中':'任务队列'}<span class="task-count">${running||state.jobs.length}</span>`;}
function renderRuns(){return heading('运行任务','任务队列',btn('新建实验','new-experiment','plus','primary'),'<span class="badge amber">演示队列</span>')+`<div class="page-scroll runs-page"><div class="runs-heading"><h2>当前会话任务</h2><p class="note" style="margin:7px 0 0">演示队列在工作区切换时持续运行。刷新页面会清空队列；已有样例结果始终独立保留。</p></div><div id="jobs-list">${jobsList()}</div><div style="margin-top:28px"><h2 style="margin-bottom:12px">已有结果样例</h2><div class="job"><div class="job-title">${icon('chart')}<strong>初始攻击力扫描 · 内置样例</strong><span class="badge teal">可查看</span><div class="actions">${btn('打开结果','show-analysis','arrow')}</div></div><div class="job-body"><span class="mono">11 候选 × 20 replicates</span><span class="muted" style="font-size:11px">3 个观察指标 · 1 个可行候选</span></div><div class="job-footer">合成数据用于评审图表、表格和检查器之间的联动。没有执行记录与可复现哈希。</div></div></div></div>`;}
function jobsList(){return state.jobs.length?state.jobs.slice().reverse().map(j=>`<article class="job"><div class="job-title">${icon(j.status==='运行中'?'clock':'terminal')}<strong>${esc(j.name)}</strong><span class="badge ${j.status==='运行中'?'teal':'amber'}">${j.status}</span><div class="actions">${j.status==='运行中'?`<button class="btn" data-cancel-job="${j.id}">${icon('cross')}取消任务</button>`:''}</div></div><div class="job-body"><span class="mono">${j.done} / ${j.total} 次</span><div class="task-progress" role="progressbar" aria-label="${esc(j.name)}进度" aria-valuenow="${j.done}" aria-valuemin="0" aria-valuemax="${j.total}"><span style="width:${j.done/j.total*100}%"></span></div><span class="muted" style="font-size:11px">${esc(j.method)} · ${j.reps} replicates</span></div><div class="job-footer">${j.status==='演示完成'?'进度演示结束；未执行仿真，未生成新的结果产物。':j.status==='已取消'?'已停止进度演示。可返回实验设计器调整后重新加入队列。':'原型正在模拟任务进度，可切页或取消。'}</div></article>`).join(''):`<div class="empty-state">${icon('terminal')}当前没有任务<br><button class="btn" data-page="designer" style="margin-top:12px">${icon('flask')}配置实验</button></div>`;}
function enqueue(){const errors=designErrors();if(errors.length){notify(errors[0]);return;}if(state.jobs.some(j=>j.status==='运行中')){notify('已有演示任务运行中，请等待完成或取消后再添加');return;}const count=designCounts();state.jobs.push({id:Date.now(),name:state.design.name,total:count.tasks,done:0,status:'运行中',method:state.method.toUpperCase(),reps:state.design.reps});state.drawer=true;renderDrawer();notify('已加入演示队列；不会执行真实仿真');}
setInterval(()=>{let changed=false;for(const job of state.jobs){if(job.status!=='运行中')continue;job.done=Math.min(job.total,job.done+Math.max(1,Math.ceil(job.total/18)));changed=true;if(job.done===job.total){job.status='演示完成';notify('队列演示完成，未生成新的仿真结果');}}if(changed){renderDrawer();if(state.page==='runs')$('#jobs-list').innerHTML=jobsList();}},700);

function renderExchange(){return heading('数据与导出','数据交换',btn('导出向导','export-dialog','download','primary'))+`<div class="page-scroll"><div class="exchange-page"><p class="exchange-intro">把当前分析带到熟悉的工具。导出内容标明样例数据来源，保留参数 ID、指标口径和 CI。</p><div class="exchange-row"><div class="exchange-icon">CSV</div><div><h2>候选结果表</h2><p>11 个候选、参数值、3 个 KPI 及 95% CI、约束判定。<br><span class="mono">UTF-8 BOM · 逗号分隔 · 百分比用 0–100 数值</span></p></div><div class="actions">${btn('下载 CSV','export-all-csv','download')}</div></div><div class="exchange-row"><div class="exchange-icon">JSON</div><div><h2>实验与候选方案快照</h2><p>当前参数草稿、实验设置、内置样例结果与来源说明。<br>样例结果绑定其默认实验设置，不会被当前草稿覆盖。</p></div><div class="actions">${btn('下载 JSON','export-json','download')}</div></div><div class="exchange-row"><div class="exchange-icon">SVG</div><div><h2>参数响应图</h2><p>导出当前主指标图，包含观测点、误差棒、基线与目标线。<br>矢量格式可供报告排版、放大与进一步编辑。</p></div><div class="actions">${btn('下载 SVG','export-svg','download')}</div></div><div class="integration-note"><strong>与商业软件的衔接</strong><br>Excel / Origin / JMP：导入 CSV 继续分析。MATLAB：使用 readtable 读取 CSV，或 jsondecode 读取 JSON。<br>“直接打开软件”、MATLAB Engine、JMP 自动化和原生工作簿连接尚未接入；当前提供文件交换。</div></div></div>`;}

function openDialog(title,body,footer=''){const d=$('#dialog');d.innerHTML=`<header class="modal-header"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="关闭对话框">${icon('cross')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}`;if(!d.open)d.showModal();}
function about(){openDialog('Sandtable · 第二版交互原型',`<p>这个原型用于评审数值策划的工作流：参数编辑 → 实验设计 → 任务队列 → 候选结果分析。</p><p>参数路径、类型与基线值参考当前仓库注册表。图表和候选结果是内置合成数据，尚未接入 Rust / WASM 内核。原型中的编辑保存在当前浏览器。</p><p>可实际体验：选择图中候选、表格排序和筛选、指标切换、批量编辑与撤销、本地保存、演示任务取消、CSV / JSON / SVG 下载。</p>`,btn('开始使用','close-dialog',null,'primary'));}
function openCommands(){openDialog('查找参数与命令',`<label for="command-input" class="muted" style="font-size:11px">输入工作区名称、参数名或参数路径</label><input id="command-input" class="command-input" placeholder="例如：攻击力、参数、导出…" autocomplete="off"/><div class="command-list" id="command-list"></div>`);renderCommands('');$('#command-input').focus();}
function renderCommands(query){const q=query.trim().toLowerCase();const matches=pages.filter(p=>`${p.label} ${p.tab}`.toLowerCase().includes(q));const params=q?paramDefinitions.filter(p=>`${p.id} ${p.name}`.toLowerCase().includes(q)).slice(0,8):[];$('#command-list').innerHTML=matches.map(p=>`<button class="command-item" data-command-page="${p.id}">${icon(p.icon)}<span>${p.label}<small>${p.tab}</small></span></button>`).join('')+params.map(p=>`<button class="command-item" data-command-param="${p.id}">${icon('table')}<span>${p.name}<small>${p.id}</small></span></button>`).join('')||'<div class="empty-state">没有匹配的命令或参数。</div>';}
function exportDialog(scope='all'){state.exportScope=scope;openDialog('导出分析数据',`<div class="export-options"><label>数据范围<select id="export-scope"><option value="all" ${scope==='all'?'selected':''}>全部 11 个候选</option><option value="filtered">当前筛选 · ${filteredCandidates().length} 个候选</option><option value="selected" ${scope==='selected'?'selected':''}>所选候选 ${state.selected}</option></select></label><label>文件格式<select id="export-format"><option value="csv">CSV · Excel / JMP / Origin</option><option value="json">JSON · 实验与参数草稿快照</option></select></label><div class="note-block">导出文件会标注 synthetic_demo 数据来源。JSON 同时包含当前编辑草稿和独立的样例实验快照，避免把未运行的修改归到旧结果上。</div></div>`,btn('取消','close-dialog',null)+btn('下载文件','confirm-export','download','primary'));}
function download(name,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(`已下载 ${name}`);}
function csvFor(rows){const cols=['data_source','candidate_id','model.warrior.attack','replicates','win_rate_pct','win_rate_ci_low_pct','win_rate_ci_high_pct','retention_d7_pct','retention_d7_ci_low_pct','retention_d7_ci_high_pct','gold_per_player','gold_ci_low','gold_ci_high','constraint_verdict'];const lines=rows.map(c=>['synthetic_demo',c.id,c.attack,20,c.win,c.win-.8,c.win+.8,c.retention,c.retention-.6,c.retention+.6,c.gold,c.gold-55,c.gold+55,verdict(c)]);return '\uFEFF'+[cols,...lines].map(row=>row.map(v=>typeof v==='number'?String(Number(v.toFixed(4))):`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');}
function exportCsv(rows=filteredCandidates()){download('sandtable-demo-candidates.csv',csvFor(rows),'text/csv;charset=utf-8');}
function snapshot(rows=candidates){return {prototype:'sandtable-workbench-v2',data_source:'synthetic_demo',notice:'Synthetic demonstration results, not produced by the Sandtable core. Current draft is not the input of these results.',draft:{parameters:state.values,experiment:{...state.design,method:state.method}},sample_result_snapshot:{parameter:'model.warrior.attack',method:'grid',range:[80,130,5],replicates:20,players:10000,days:30,crn:true,units:{win_rate:'percent_0_100',retention_d7:'percent_0_100',gold_per_player:'unscaled'},constraints:Object.fromEntries(Object.values(metrics).map(m=>[m.id,{operator:m.op,threshold:m.target,ci_method:'illustrative_symmetric_interval'}])),candidates:rows.map(c=>({...c,verdict:verdict(c),ci:Object.fromEntries(Object.entries(metrics).map(([k,m])=>[k,[Number((c[k]-m.ci).toFixed(3)),Number((c[k]+m.ci).toFixed(3))]]))}))}};}
function exportJson(rows=candidates){download('sandtable-demo-snapshot.json',JSON.stringify(snapshot(rows),null,2),'application/json');}
function exportSvg(){let markup=chart(state.metric);const m=metrics[state.metric];markup=markup.replace('<svg ',`<svg xmlns="http://www.w3.org/2000/svg" `).replace(/<title>[^<]*<\/title>/,`<title>${m.label} · 合成演示数据</title><desc>Source: synthetic_demo. Not generated by the Sandtable core. Points and illustrative 95% CI; no interpolation.</desc><style>.chart-grid{stroke:#e7edef;stroke-width:1}.chart-text{fill:#6c7e86;font:11px monospace}.chart-label{fill:#62777e;font:11px sans-serif}.chart-ci{stroke:#55a3a6;stroke-width:1.5}.chart-point{fill:white;stroke:#087f86;stroke-width:2}.selected .chart-point{fill:#ba7e20;stroke:white;stroke-width:2.5}.selected .chart-ci{stroke:#aa7216;stroke-width:2}</style><rect width="100%" height="100%" fill="white"/>`);download(`sandtable-demo-${m.id}.svg`,markup,'image/svg+xml');}
function selectCandidate(id,focus=false){if(!candidates.some(c=>c.id===id))return;state.selected=id;if(state.page==='analysis'){const center=$('.analysis-center'),oldScroll=center.scrollTop;render();$('.analysis-center').scrollTop=oldScroll;if(focus){const target=$(`.candidate-select[data-candidate="${id}"]`);target?.focus({preventScroll:true});target?.closest('tr')?.scrollIntoView({block:'nearest'});}}}
function confirmResetAll(){openDialog('恢复所有参数的默认基线值',`<p>将把候选方案 A 中 ${changedParams().length} 项变更恢复为注册表默认值。可以通过“撤销”恢复本次修改。已保存的浏览器草稿在再次保存前保持原值。</p>`,btn('取消','close-dialog',null)+btn('恢复默认值','confirm-reset',null,'primary'));}
const actions={
  'toggle-explorer':()=>$('#desktop').classList.toggle('explorer-collapsed'),
  'toggle-inspector':()=>{state.inspector=!state.inspector;render();},
  'toggle-tasks':()=>{state.drawer=!state.drawer;renderDrawer();},'all-jobs':()=>navigate('runs'),
  'about':about,'project-info':()=>openDialog('RPG 平衡实验室',`<p>当前打开的是内置样例项目。默认基线来自 Sandtable 参数注册表；候选方案 A 的修改保存在此浏览器。</p><p>真正的项目文件打开、项目版本管理与内核运行仍需要后续接入。本原型不显示伪造的配置哈希或文件保存状态。</p>`,btn('打开参数表','go-parameters','table','primary')),
  'commands':openCommands,'close-dialog':()=>$('#dialog').close(),
  'go-parameters':()=>{$('#dialog').close();navigate('parameters');},
  'show-analysis':()=>navigate('analysis'),'edit-experiment':()=>navigate('designer'),
  'new-experiment':()=>navigate('designer'),'save':persist,
  'undo':()=>{const prev=state.history.pop();if(!prev){notify('当前会话没有可撤销的修改');return;}state.values=prev;markDirty();render();notify('已撤销上一次参数修改');},
  'reset-all':confirmResetAll,'confirm-reset':()=>{state.history.push({...state.values});state.values={...defaults};markDirty();$('#dialog').close();render();notify('已恢复默认基线值，可撤销');},
  'reset-single':()=>{commitParam(state.paramFocus,defaults[state.paramFocus]);notify('已恢复此项基线值');},
  'clear-selection':()=>{state.paramSelected.clear();render();},
  'bulk-multiply':()=>{const factor=Number($('#bulk-factor').value);if(!Number.isFinite(factor)||factor<0){notify('倍率需为非负有限数值');return;}const next={...state.values};for(const id of state.paramSelected){const p=paramDefinitions.find(p=>p.id===id);const value=p.type==='f64'?Number((next[id]*factor).toPrecision(10)):Math.round(next[id]*factor);const error=validateParam(p,value);if(error){notify(`${p.name}：${error}，未应用批量修改`);return;}next[id]=value;}state.history.push({...state.values});state.values=next;markDirty();render();notify(`已修改 ${state.paramSelected.size} 个参数，可撤销`);},
  'adopt':()=>{const c=selectedCandidate();state.history.push({...state.values});state.values['model.warrior.attack']=c.attack;state.paramFocus='model.warrior.attack';state.paramSearch='';state.changedOnly=false;markDirty();navigate('parameters');notify(`已复制 ${c.id} 的攻击力 ${c.attack} 到候选方案 A`);},
  'enqueue':enqueue,'export-dialog':()=>exportDialog(),'candidate-export':()=>exportDialog('selected'),
  'export-csv':()=>exportCsv(),'export-all-csv':()=>exportCsv(candidates),'export-json':()=>exportJson(),'export-svg':exportSvg,
  'confirm-export':()=>{const scope=$('#export-scope').value,format=$('#export-format').value;const rows=scope==='selected'?[selectedCandidate()]:scope==='filtered'?filteredCandidates():candidates;if(format==='json')exportJson(rows);else exportCsv(rows);$('#dialog').close();},
  'shortcuts':()=>openDialog('键盘操作',`<div class="shortcut-row"><span>查找参数与命令</span><kbd>Ctrl / ⌘ + K</kbd></div><div class="shortcut-row"><span>保存参数草稿</span><kbd>Ctrl / ⌘ + S</kbd></div><div class="shortcut-row"><span>撤销参数修改</span><kbd>Ctrl / ⌘ + Z</kbd></div><div class="shortcut-row"><span>候选表选择上一项 / 下一项</span><kbd>↑ / ↓</kbd></div><div class="shortcut-row"><span>文档标签切换</span><kbd>← / → · Home / End</kbd></div><div class="shortcut-row"><span>图中观测点选择</span><kbd>Tab → Enter</kbd></div><div class="shortcut-row"><span>关闭对话框</span><kbd>Esc</kbd></div>`,btn('关闭','close-dialog',null)),
};
document.addEventListener('click',event=>{
  const el=event.target.closest('button,[data-candidate],tr[data-candidate]');if(!el)return;
  if(el.dataset.action){actions[el.dataset.action]?.();return;}
  if(el.dataset.page){navigate(el.dataset.page);return;}
  if(el.dataset.candidate){selectCandidate(el.dataset.candidate);return;}
  if(el.dataset.view){state.resultView=el.dataset.view;render();return;}
  if(el.dataset.sort){if(state.sort===el.dataset.sort)state.sortDir*=-1;else{state.sort=el.dataset.sort;state.sortDir=1;}render();return;}
  if(el.dataset.paramFocus){state.paramFocus=el.dataset.paramFocus;render();return;}
  if(el.dataset.method){state.method=el.dataset.method;render();return;}
  if(el.dataset.cancelJob){const job=state.jobs.find(j=>j.id===Number(el.dataset.cancelJob));if(job)job.status='已取消';renderDrawer();if(state.page==='runs')$('#jobs-list').innerHTML=jobsList();notify('演示任务已取消');return;}
  if(el.dataset.commandPage){$('#dialog').close();navigate(el.dataset.commandPage);return;}
  if(el.dataset.commandParam){state.paramFocus=el.dataset.commandParam;state.paramSearch=el.dataset.commandParam;state.paramGroup='all';state.changedOnly=false;$('#dialog').close();navigate('parameters');return;}
});
document.addEventListener('focusin',event=>{
  if(event.target.dataset?.paramValue && state.page==='parameters'){state.paramFocus=event.target.dataset.paramValue;$$('[data-param-row]').forEach(row=>row.classList.toggle('selected',row.dataset.paramRow===state.paramFocus));const inspector=$('.parameters-body > .selection-inspector');if(inspector)inspector.outerHTML=parameterInspector();}
});
document.addEventListener('input',event=>{
  const el=event.target;
  if(el.id==='parameter-search'){state.paramSearch=el.value;updateParameterFilter();}
  if(el.id==='command-input')renderCommands(el.value);
  if(el.dataset.design){const k=el.dataset.design;state.design[k]=['name','sampling'].includes(k)?el.value:el.value===''?NaN:Number(el.value);const summary=$('#design-summary');if(summary)summary.innerHTML=designSummary();}
});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.id==='metric-select'){state.metric=el.value;render();}
  if(el.id==='result-filter'){state.resultFilter=el.value;render();}
  if(el.id==='parameter-group'){state.paramGroup=el.value;updateParameterFilter();}
  if(el.id==='changed-only'){state.changedOnly=el.checked;render();}
  if(el.id==='paired-random'){state.design.paired=el.checked;}
  if(el.id==='sampling-method')state.design.sampling=el.value;
  if(el.id==='all-params'){visibleParams().forEach(p=>el.checked?state.paramSelected.add(p.id):state.paramSelected.delete(p.id));render();}
  if(el.dataset.paramCheck){if(el.checked)state.paramSelected.add(el.dataset.paramCheck);else state.paramSelected.delete(el.dataset.paramCheck);render();}
  if(el.dataset.paramValue){commitParam(el.dataset.paramValue,el.value.trim()===''?NaN:Number(el.value),el);}
});
document.addEventListener('keydown',event=>{
  const modifier=event.ctrlKey||event.metaKey;
  if(modifier&&event.key.toLowerCase()==='k'){event.preventDefault();openCommands();return;}
  if(modifier&&event.key.toLowerCase()==='s'){event.preventDefault();persist();return;}
  const editing=['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName);
  if(modifier&&event.key.toLowerCase()==='z'&&!editing&&!$('#dialog').open){event.preventDefault();actions.undo();return;}
  if(event.key==='?'&&!editing&&!$('#dialog').open){actions.shortcuts();return;}
  const tab=event.target.closest('.document-tab');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=$$('.document-tab');let i=tabs.indexOf(tab);i=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;navigate(tabs[i].dataset.page);$(`#tab-${state.page}`)?.focus();return;}
  const candidate=event.target.closest('[data-candidate]');if(candidate){if(event.key==='Enter'||event.key===' '){event.preventDefault();selectCandidate(candidate.dataset.candidate,true);return;}if(['ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const rows=filteredCandidates(),i=rows.findIndex(c=>c.id===candidate.dataset.candidate),next=rows[Math.max(0,Math.min(rows.length-1,i+(event.key==='ArrowDown'?1:-1)))];if(next)selectCandidate(next.id,true);}}
  if(event.target.id==='command-input'&&event.key==='ArrowDown'){event.preventDefault();$('.command-item')?.focus();}
  if(event.target.closest('.command-item')&&['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();const items=$$('.command-item'),i=items.indexOf(event.target.closest('.command-item'));items[(i+(event.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();}
  if(elIsCell(event.target)&&event.key==='Escape'){event.target.value=state.values[event.target.dataset.paramValue];event.target.classList.remove('invalid');const err=$(`#error-${event.target.dataset.paramValue.replaceAll('.','-')}`);if(err)err.textContent='';event.target.blur();}
});
function elIsCell(el){return Boolean(el.dataset?.paramValue);}
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(pages.some(p=>p.id===id)){state.page=id;render();}});
render();

let resizeTimer;
window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.page==='analysis')render();},60);});
